#pragma once
#include <vector>

// The machines' colour presets the game has (DT_MachineColorPreset*), generated by
// Tools\ExtractGameImages.py --catalog. Their swatches are GameImages\color\ColorPreset<NN>.png.
namespace SonicRacingSaveManager::Data::ColorCatalog {

struct ColorPreset {
    int id;               // EMachineColorPresetId: ColorPreset<id>
    const char* machine;  // the machine whose colours they are ("SPD_01"), "" for the others
    int festival;         // a festival team's colour number (FestaTeamColor<n>), 0 for the others
    // Its values, as the game copies them into a machine (UserMachineCustomizeData): the body's, tyres'
    // and cockpit's (colour, surface) x 3 and glow, in that order
    int values[21];
};

const std::vector<ColorPreset>& Presets();

} // namespace SonicRacingSaveManager::Data::ColorCatalog
